import type { BenchmarkQuery } from './dataset';
import type { QueryEvaluation } from './evaluate';

/** Evaluation result for a single query (including the original query definition for detailed output). */
export interface PerQueryResult {
  query: BenchmarkQuery;
  evaluation: QueryEvaluation;
}

export interface VolumeSummary {
  total: number;
  hits: number;
  avgEntityRecall: number;
  avgPhraseRecall: number;
  avgCombinedRecall: number;
}

export interface BenchmarkReport {
  total: number;
  hits: number;
  strictHitRate: number;
  avgEntityRecall: number;
  avgPhraseRecall: number;
  avgCombinedRecall: number;
  byVolume: Record<string, VolumeSummary>;
}

const average = (values: readonly number[]): number =>
  values.length === 0 ? 0 : values.reduce((sum, value) => sum + value, 0) / values.length;

const toVolumeSummary = (items: readonly PerQueryResult[]): VolumeSummary => ({
  total: items.length,
  hits: items.filter(({ evaluation }) => evaluation.hit).length,
  avgEntityRecall: average(items.map(({ evaluation }) => evaluation.entityRecall)),
  avgPhraseRecall: average(items.map(({ evaluation }) => evaluation.phraseRecall)),
  avgCombinedRecall: average(items.map(({ evaluation }) => evaluation.combinedRecall)),
});

export const aggregateResults = (results: readonly PerQueryResult[]): BenchmarkReport => {
  const byVolume = new Map<number, PerQueryResult[]>();
  for (const result of results) {
    const list = byVolume.get(result.query.volume) ?? [];
    list.push(result);
    byVolume.set(result.query.volume, list);
  }

  const grouped: Record<string, VolumeSummary> = {};
  for (const [volume, items] of byVolume) {
    grouped[String(volume)] = toVolumeSummary(items);
  }

  const total = results.length;
  const hits = results.filter(({ evaluation }) => evaluation.hit).length;

  return {
    total,
    hits,
    strictHitRate: total === 0 ? 0 : hits / total,
    avgEntityRecall: average(results.map(({ evaluation }) => evaluation.entityRecall)),
    avgPhraseRecall: average(results.map(({ evaluation }) => evaluation.phraseRecall)),
    avgCombinedRecall: average(results.map(({ evaluation }) => evaluation.combinedRecall)),
    byVolume: grouped,
  };
};

benchmark/evaluate.ts.content:
import type { BenchmarkExpectation } from './dataset';

/**
 * Recall evaluation: compare retrieval context with expectations (entities + key phrases).
 *
 * - entityRecall: proportion of expected entities appearing in context
 * - phraseRecall: proportion of expected key phrases appearing in context (exact substring)
 * - combinedRecall: recall proportion after merging entities + phrases
 * - hit: strict hit (all expected appear)
 *
 * Empty expected set is treated as 1.0 (no missing items).
 */

export interface QueryEvaluation {
  foundEntities: string[];
  missingEntities: string[];
  foundPhrases: string[];
  missingPhrases: string[];
  entityRecall: number;
  phraseRecall: number;
  combinedRecall: number;
  hit: boolean;
}

const findPresent = (needles: readonly string[], haystack: string): string[] =>
  needles.filter((needle) => haystack.includes(needle));

const findMissing = (needles: readonly string[], haystack: string): string[] =>
  needles.filter((needle) => !haystack.includes(needle));

const ratio = (found: number, total: number): number => (total === 0 ? 1 : found / total);

export const evaluateRecall = (
  context: string,
  expectation: BenchmarkExpectation,
): QueryEvaluation => {
  const foundEntities = findPresent(expectation.entities, context);
  const foundPhrases = findPresent(expectation.phrases, context);

  const entityRecall = ratio(foundEntities.length, expectation.entities.length);
  const phraseRecall = ratio(foundPhrases.length, expectation.phrases.length);
  const combinedRecall = ratio(
    foundEntities.length + foundPhrases.length,
    expectation.entities.length + expectation.phrases.length,
  );

  return {
    foundEntities,
    missingEntities: findMissing(expectation.entities, context),
    foundPhrases,
    missingPhrases: findMissing(expectation.phrases, context),
    entityRecall,
    phraseRecall,
    combinedRecall,
    hit: entityRecall === 1 && phraseRecall === 1,
  };
};

