import { describe, expect, it } from 'bun:test';

import { formatMarkdownReport } from './format';
import type { PerQueryResult } from './report';
import { aggregateResults } from './report';

const resultOf = (overrides: Partial<PerQueryResult>): PerQueryResult => ({
  query: {
    id: 'v1-q1',
    volume: 1,
    story: 'The Rift of Perfect Memory',
    fact: 'Facts',
    query: 'Questions',
    topK: 5,
    expectation: { entities: ['Kai'], phrases: ['Perfect Memory'] },
  },
  evaluation: {
    foundEntities: ['Kai'],
    missingEntities: [],
    foundPhrases: ['Perfect Memory'],
    missingPhrases: ['Deep Purple Pulse'],
    entityRecall: 1,
    phraseRecall: 0.5,
    combinedRecall: 0.5,
    hit: false,
  },
  ...overrides,
});

describe('formatMarkdownReport', () => {
  it('renders totals and per-query rows', () => {
    const results = [resultOf({})];
    const report = aggregateResults(results);
    const markdown = formatMarkdownReport(report, results);

    expect(markdown).toContain('# GraphRAG Recall Benchmark');
    expect(markdown).toContain('Total Queries: 1');
    expect(markdown).toContain('Exact Match: 0 / 1');
    expect(markdown).toContain('Average Entity Recall: 100.0%');
    expect(markdown).toContain('| v1-q1 | Volume 1 | The Rift of Perfect Memory | ❌ | 100% | 50% | - | Deep Purple Pulse |');
  });

  it('lists missing items in the detail row', () => {
    const results = [
      resultOf({
        evaluation: {
          foundEntities: [],
          missingEntities: ['Kai', 'Lao Chen'],
          foundPhrases: [],
          missingPhrases: ['Perfect Memory'],
          entityRecall: 0,
          phraseRecall: 0,
          combinedRecall: 0,
          hit: false,
        },
      }),
    ];
    const report = aggregateResults(results);
    const markdown = formatMarkdownReport(report, results);

    expect(markdown).toContain('| Kai, Lao Chen | Perfect Memory |');
  });
});

benchmark/context.ts.content:
import type { RetrievalResult } from '../retrieval/types/retrieval';

/**
 * Extract matchable context text from retrieval API responses:
 * - name / members / summary of each hit community
 * - text of each evidence (original sub-block, primary basis for recall)
 * - optional: answer (LLM-generated response)
 *
 * Recall by default only looks at the "retrieval context" (communities + evidence), not including answer,
 * to avoid mixing generation quality into retrieval recall; enable it via `includeAnswer: true` when end-to-end metrics are needed.
 */

export interface RetrievedContextOptions {
  includeAnswer?: boolean;
}

const pushIfPresent = (parts: string[], text: string | undefined): void => {
  if (typeof text === 'string' && text.length > 0) {
    parts.push(text);
  }
};

export const buildRetrievedContext = (
  result: RetrievalResult,
  options: RetrievedContextOptions = {},
): string => {
  const parts: string[] = [];

  for (const community of result.communities) {
    pushIfPresent(parts, community.name);
    for (const member of community.members) {
      pushIfPresent(parts, member);
    }
    pushIfPresent(parts, community.summary);
  }

  for (const snippet of result.evidence) {
    pushIfPresent(parts, snippet.text);
  }

  if (options.includeAnswer === true) {
    pushIfPresent(parts, result.answer);
  }

  return parts.join('\n');
};

benchmark/evaluate.test.ts.content:
import { describe, expect, it } from 'bun:test';

import { evaluateRecall } from './evaluate';

describe('evaluateRecall', () => {
  it('marks a strict hit when every entity and phrase is present', () => {
    const evaluation = evaluateRecall('Kai Old Chen Metal Shards Echo Bazaar', {
      entities: ['Kai', 'Old Chen'],
      phrases: ['Metal Shards', 'Echo Bazaar'],
    });
    expect(evaluation.entityRecall).toBe(1);
    expect(evaluation.phraseRecall).toBe(1);
    expect(evaluation.combinedRecall).toBe(1);
    expect(evaluation.hit).toBe(true);
    expect(evaluation.missingEntities).toEqual([]);
    expect(evaluation.missingPhrases).toEqual([]);
  });

  it('reports partial recall when some expectations are missing', () => {
    const evaluation = evaluateRecall('Kai Old Chen', {
      entities: ['Kai', 'Old Chen', 'Prometheus'],
      phrases: ['Metal Shards', 'Zero Point Archives'],
    });
    expect(evaluation.entityRecall).toBe(2 / 3);
    expect(evaluation.phraseRecall).toBe(0);
    expect(evaluation.combinedRecall).toBe(2 / 5);
    expect(evaluation.hit).toBe(false);
    expect(evaluation.missingEntities).toEqual(['Prometheus']);
    expect(evaluation.missingPhrases).toEqual(['Metal Shards', 'Zero Point Archives']);
  });

  it('returns zero recall when nothing matches', () => {
    const evaluation = evaluateRecall('Unrelated Content', {
      entities: ['Kai'],
      phrases: ['Zero Point Archives'],
    });
    expect(evaluation.entityRecall).toBe(0);
    expect(evaluation.phraseRecall).toBe(0);
    expect(evaluation.hit).toBe(false);
  });

  it('treats an empty expectation as fully satisfied', () => {
    const evaluation = evaluateRecall('anything', { entities: [], phrases: [] });
    expect(evaluation.entityRecall).toBe(1);
    expect(evaluation.phraseRecall).toBe(1);
    expect(evaluation.hit).toBe(true);
  });
});

benchmark/run.test.ts.content:
import { describe, expect, it } from 'bun:test';

import type { BuildJob } from '../build/buildRegistry';
import type { BenchmarkQuery } from './dataset';
import { BENCHMARK_QUERIES } from './dataset';
import type { RagApiClient } from './client';
import { main, parseCliOptions, runBenchmark } from './run';

const queryOf = (id: string, volume: 1 | 2 | 3, query: string): BenchmarkQuery => ({
  id,
  volume,
  story: 'Storyline',
  fact: 'Fact',
  query,
  topK: 3,
  expectation: { entities: ['Kai'], phrases: ['Metal Shards'] },
});

const makeFakeClient = (options: {
  hitIds?: ReadonlySet<string>;
  buildStatus?: BuildJob['status'];
  buildError?: string;
} = {}): RagApiClient & { buildFolderCalls: string[] } => {
  const hitIds = options.hitIds ?? new Set(BENCHMARK_QUERIES.map(({ id }) => id));
  const buildFolderCalls: string[] = [];
  return {
    buildFolderCalls,
    buildFolder: async ({ path }) => {
      buildFolderCalls.push(path);
      return 'build-1';
    },
    getBuild: async () => ({
      id: 'build-1',
      status: options.buildStatus ?? 'succeeded',
      title: 't',
      namespace: 'ns',
      createdAt: 0,
      ...(options.buildError !== undefined ? { error: options.buildError } : {}),
    }),
    retrieve: async ({ query }) => {
      const item = BENCHMARK_QUERIES.find((candidate) => candidate.query === query);
      const context =
        item !== undefined && hitIds.has(item.id)
          ? [...item.expectation.entities, ...item.expectation.phrases].join(' ')
          : '';
      return {
        query,
        communities: [],
        evidence: context.length > 0 ? [{ text: context }] : [],
        answer: '',
      };
    },
  };
};

describe('runBenchmark', () => {
  it('evaluates each dataset query and aggregates the report', async () => {
    const client = makeFakeClient();
    const outcome = await runBenchmark({ client, namespace: 'ns' });

    expect(outcome.report.total).toBe(BENCHMARK_QUERIES.length);
    expect(outcome.report.hits).toBe(BENCHMARK_QUERIES.length);
    expect(outcome.report.strictHitRate).toBe(1);
    expect(outcome.results.length).toBe(BENCHMARK_QUERIES.length);
  });

  it('counts misses when the retrieval context lacks expectations', async () => {
    const client = makeFakeClient({ hitIds: new Set<string>() });
    const outcome = await runBenchmark({ client, namespace: 'ns' });

    expect(outcome.report.hits).toBe(0);
    expect(outcome.report.strictHitRate).toBe(0);
  });

  it('supports a custom dataset and topK override', async () => {
    const dataset = [queryOf('t1', 1, 'q1'), queryOf('t2', 2, 'q2')];
    const retrieveCalls: Array<{ query: string; topK: number; namespace: string }> = [];
    const client = {
      buildFolder: async () => 'build-1',
      getBuild: async () => jobOf('succeeded'),
      retrieve: async (input: { query: string; topK: number; namespace: string }) => {
        retrieveCalls.push(input);
        const hit = input.query === 'q1';
        return {
          query: input.query,
          communities: [],
          evidence: hit ? [{ text: 'Kai Metal Shards' }] : [],
          answer: '',
        };
      },
    } as unknown as RagApiClient;

    const outcome = await runBenchmark({ client, namespace: 'ns', dataset, topK: 7 });

    expect(outcome.report.total).toBe(2);
    expect(outcome.report.hits).toBe(1);
    expect(retrieveCalls[0]?.topK).toBe(7);
    expect(retrieveCalls[1]?.topK).toBe(7);
  });

  it('builds via the API before retrieving when build is enabled', async () => {
    const client = makeFakeClient();
    const outcome = await runBenchmark({
      client,
      namespace: 'ns',
      outlinePath: '/outline',
      build: true,
      pollIntervalMs: 1,
    });

    expect(client.buildFolderCalls).toEqual(['/outline']);
    expect(outcome.report.total).toBe(BENCHMARK_QUERIES.length);
  });

  it('requires outlinePath when build is enabled', async () => {
    const client = makeFakeClient();
    await expect(runBenchmark({ client, namespace: 'ns', build: true })).rejects.toThrow(
      'outlinePath is required',
    );
  });

  it('logs the retrieval flow when verbose is enabled', async () => {
    const client = makeFakeClient();
    const logged: string[] = [];
    const originalLog = console.log;
    console.log = (message?: unknown) => {
      logged.push(String(message));
    };
    try {
      await runBenchmark({ client, namespace: 'ns', verbose: true });
    } finally {
      console.log = originalLog;
    }

    expect(logged.some((line) => line.startsWith('[retrieve] v1-q1 ·'))).toBe(true);
    expect(logged.some((line) => line.includes('evidence[0]:'))).toBe(true);
  });

  it('logs and rethrows a retrieve failure when verbose is enabled', async () => {
    const failing = {
      buildFolder: async () => 'build-1',
      getBuild: async () => jobOf('succeeded'),
      retrieve: async () => {
        throw new Error('RAG API 500: boom');
      },
    } as unknown as RagApiClient;
    const errors: string[] = [];
    const originalError = console.error;
    console.error = (message?: unknown) => {
      errors.push(String(message));
    };
    try {
      await expect(
        runBenchmark({ client: failing, namespace: 'ns', verbose: true }),
      ).rejects.toThrow('RAG API 500: boom');
    } finally {
      console.error = originalError;
    }

    expect(errors.some((line) => line.includes('[retrieve] v1-q1 FAILED'))).toBe(true);
  });

  it('propagates build failures', async () => {
    const client = makeFakeClient({ buildStatus: 'failed', buildError: 'boom' });
    await expect(
      runBenchmark({ client, namespace: 'ns', outlinePath: '/outline', build: true }),
    ).rejects.toThrow('RAG build failed: boom');
  });
});

describe('parseCliOptions', () => {
  it('applies defaults', () => {
    const cli = parseCliOptions([], {});
    expect(cli.baseUrl).toBe('http://localhost:3000');
    expect(cli.namespace).toBe('default-namespace');
    expect(cli.build).toBe(false);
    expect(cli.includeAnswer).toBe(false);
    expect(cli.verbose).toBe(false);
    expect(cli.topK).toBeUndefined();
  });

  it('reads flags and env overrides', () => {
    const cli = parseCliOptions(
      ['--base-url', 'http://127.0.0.1:4000', '--topK', '7', '--build', '--include-answer', '--verbose'],
      { RAG_NAMESPACE: 'ns-env', RAG_OUTLINE_PATH: '/env/outline' },
    );
    expect(cli.baseUrl).toBe('http://127.0.0.1:4000');
    expect(cli.namespace).toBe('ns-env');
    expect(cli.outlinePath).toBe('/env/outline');
    expect(cli.build).toBe(true);
    expect(cli.includeAnswer).toBe(true);
    expect(cli.verbose).toBe(true);
    expect(cli.topK).toBe(7);
  });
});

describe('main', () => {
  it('runs the benchmark and prints a markdown report', async () => {
    const client = makeFakeClient();
    const logged: string[] = [];
    const originalLog = console.log;
    console.log = (message?: unknown) => {
      logged.push(String(message));
    };
    try {
      await main([], {}, () => client);
    } finally {
      console.log = originalLog;
    }

    const output = logged.join('\n');
    expect(output).toContain('# GraphRAG Recall Benchmark');
    expect(output).toContain(`Total Queries: ${BENCHMARK_QUERIES.length}`);
    expect(output).toContain('| v1-q1 | Volume 1 |');
  });
});

const jobOf = (status: BuildJob['status']): BuildJob => ({
  id: 'build-1',
  status,
  title: 't',
  namespace: 'ns',
  createdAt: 0,
});

