import { describe, expect, it } from 'bun:test';

import type { RetrievalResult } from '../retrieval/types/retrieval';
import { buildRetrievedContext } from './context';

const sample = (overrides: Partial<RetrievalResult> = {}): RetrievalResult => ({
  query: 'q',
  communities: [
    {
      id: 'c1',
      name: 'Community A',
      summary: 'Community summary',
      members: ['Kai', 'Old Chen'],
      matchedEntities: ['Kai'],
      score: 0.9,
    },
  ],
  evidence: [{ text: 'Evidence original snippet' }],
  answer: 'LLM generated answer',
  ...overrides,
});

describe('buildRetrievedContext', () => {
  it('includes community name, members and summary', () => {
    const context = buildRetrievedContext(sample());
    expect(context).toContain('Community A');
    expect(context).toContain('Kai');
    expect(context).toContain('Old Chen');
    expect(context).toContain('Community summary');
  });

  it('includes evidence text', () => {
    const context = buildRetrievedContext(sample());
    expect(context).toContain('Evidence original snippet');
  });

  it('excludes answer by default', () => {
    const context = buildRetrievedContext(sample());
    expect(context).not.toContain('LLM generated answer');
  });

  it('includes answer when includeAnswer is true', () => {
    const context = buildRetrievedContext(sample(), { includeAnswer: true });
    expect(context).toContain('LLM generated answer');
  });

  it('skips empty optional fields', () => {
    const context = buildRetrievedContext(
      sample({
        communities: [{ id: 'c1', members: [], matchedEntities: [], score: 0 }],
        evidence: [],
        answer: '',
      }),
    );
    expect(context).toBe('');
  });
});

benchmark/format.ts.content:
import type { BenchmarkReport, PerQueryResult } from './report';

const percent = (value: number, digits = 1): string => `${(value * 100).toFixed(digits)}%`;

const joinMissing = (items: readonly string[]): string => (items.length === 0 ? '-' : items.join('、'));

/** Render the aggregate report as Markdown, for easy viewing and archiving in the terminal. */
export const formatMarkdownReport = (
  report: BenchmarkReport,
  results: readonly PerQueryResult[],
): string => {
  const lines: string[] = [];
  lines.push('# GraphRAG Recall Benchmark');
  lines.push('');
  lines.push(`- Total queries: ${report.total}`);
  lines.push(`- Strict hits: ${report.hits} / ${report.total} (${percent(report.strictHitRate)})`);
  lines.push(`- Average entity recall: ${percent(report.avgEntityRecall)}`);
  lines.push(`- Average information recall: ${percent(report.avgPhraseRecall)}`);
  lines.push(`- Average combined recall: ${percent(report.avgCombinedRecall)}`);
  lines.push('');
  lines.push('## Volume Statistics');
  lines.push('');
  lines.push('| Volume | Queries | Hits | Hit Rate | Entity Recall | Information Recall |');
  lines.push('|---|:---:|:---:|:---:|:---:|:---:|');
  for (const [volume, summary] of Object.entries(report.byVolume)) {
    const row = [
      `Volume ${volume}`,
      String(summary.total),
      String(summary.hits),
      percent(summary.total === 0 ? 0 : summary.hits / summary.total),
      percent(summary.avgEntityRecall),
      percent(summary.avgPhraseRecall),
    ].join(' | ');
    lines.push(`| ${row} |`);
  }
  lines.push('');
  lines.push('## Per-Question Details');
  lines.push('');
  lines.push('| id | Volume | Storyline | Hits | Entity Recall | Information Recall | Missing Entities | Missing Information |');
  lines.push('|---|:---:|---|:---:|:---:|:---:|---|---|');
  for (const { query, evaluation } of results) {
    const row = [
      query.id,
      `Volume ${query.volume}`,
      query.story,
      evaluation.hit ? '✅' : '❌',
      percent(evaluation.entityRecall, 0),
      percent(evaluation.phraseRecall, 0),
      joinMissing(evaluation.missingEntities),
      joinMissing(evaluation.missingPhrases),
    ].join(' | ');
    lines.push(`| ${row} |`);
  }
  lines.push('');
  return lines.join('\n');
};

benchmark/client.ts.content:
import type { BuildJob } from '../build/buildRegistry';
import type { RetrievalResult } from '../retrieval/types/retrieval';

/**
 * RAG HTTP API client. Only depends on the three endpoints required by the benchmark:
 * - POST /api/rag/folders (build index)
 * - GET  /api/rag/builds/:buildId (query build status)
 * - POST /api/rag/retrieve (retrieve)
 *
 * `fetch` is injectable for testing.
 */

export interface BuildFolderInput {
  path: string;
  namespace: string;
  exclude?: readonly string[];
}

export interface RetrieveInput {
  query: string;
  topK: number;
  namespace: string;
}

export interface RagApiClient {
  buildFolder(input: BuildFolderInput): Promise<string>;
  getBuild(buildId: string, namespace: string): Promise<BuildJob>;
  retrieve(input: RetrieveInput): Promise<RetrievalResult>;
}

export type FetchLike = (input: string | URL | Request, init?: RequestInit) => Promise<Response>;

export interface RagApiClientOptions {
  baseUrl: string;
  fetch?: FetchLike;
}

const withNamespaceHeader = (namespace: string, init?: RequestInit): RequestInit => {
  const headers = new Headers(init?.headers);
  headers.set('x-namespace', namespace);
  return { ...init, headers };
};

const readJson = async (response: Response): Promise<unknown> => {
  const body = (await response.json()) as unknown;
  if (!response.ok) {
    throw new Error(`RAG API ${response.status}: ${JSON.stringify(body)}`);
  }
  return body;
};

const readBuildId = (body: unknown): string => {
  const buildId = (body as { buildId?: unknown })?.buildId;
  if (typeof buildId !== 'string' || buildId.length === 0) {
    throw new Error('RAG API buildFolder: missing buildId in response');
  }
  return buildId;
};

export const createRagApiClient = (options: RagApiClientOptions): RagApiClient => {
  const { baseUrl } = options;
  const fetchImpl = options.fetch ?? fetch;
  const apiRoot = baseUrl.replace(/\/+$/, '');

  const buildFolder = async (input: BuildFolderInput): Promise<string> => {
    const response = await fetchImpl(
      `${apiRoot}/api/rag/folders`,
      withNamespaceHeader(input.namespace, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          path: input.path,
          namespace: input.namespace,
          ...(input.exclude && input.exclude.length > 0 ? { exclude: [...input.exclude] } : {}),
        }),
      }),
    );
    return readBuildId(await readJson(response));
  };

  const getBuild = async (buildId: string, namespace: string): Promise<BuildJob> => {
    const response = await fetchImpl(
      `${apiRoot}/api/rag/builds/${encodeURIComponent(buildId)}`,
      withNamespaceHeader(namespace),
    );
    return (await readJson(response)) as BuildJob;
  };

  const retrieve = async (input: RetrieveInput): Promise<RetrievalResult> => {
    const response = await fetchImpl(
      `${apiRoot}/api/rag/retrieve`,
      withNamespaceHeader(input.namespace, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ query: input.query, topK: input.topK }),
      }),
    );
    return (await readJson(response)) as RetrievalResult;
  };

  return { buildFolder, getBuild, retrieve };
};

