import { describe, expect, it } from 'bun:test';

import type { BenchmarkQuery } from './dataset';
import type { QueryEvaluation } from './evaluate';
import type { PerQueryResult } from './report';
import { aggregateResults } from './report';

const queryOf = (id: string, volume: 1 | 2 | 3): BenchmarkQuery => ({
  id,
  volume,
  story: 'Storyline',
  fact: 'Fact',
  query: `q-${id}`,
  topK: 5,
  expectation: { entities: ['A'], phrases: ['P'] },
});

const evaluationOf = (hit: boolean, entityRecall: number, phraseRecall: number): QueryEvaluation => ({
  foundEntities: hit ? ['A'] : [],
  missingEntities: hit ? [] : ['A'],
  foundPhrases: hit ? ['P'] : [],
  missingPhrases: hit ? [] : ['P'],
  entityRecall,
  phraseRecall,
  combinedRecall: hit ? 1 : 0,
  hit,
});

const resultOf = (id: string, volume: 1 | 2 | 3, evaluation: QueryEvaluation): PerQueryResult => ({
  query: queryOf(id, volume),
  evaluation,
});

describe('aggregateResults', () => {
  it('returns zeroed summary for empty input', () => {
    const report = aggregateResults([]);
    expect(report.total).toBe(0);
    expect(report.hits).toBe(0);
    expect(report.strictHitRate).toBe(0);
    expect(report.avgEntityRecall).toBe(0);
    expect(report.byVolume).toEqual({});
  });

  it('aggregates hits and averages across queries', () => {
    const results = [
      resultOf('v1-q1', 1, evaluationOf(true, 1, 1)),
      resultOf('v1-q2', 1, evaluationOf(false, 0.5, 0)),
      resultOf('v2-q1', 2, evaluationOf(true, 1, 1)),
    ];
    const report = aggregateResults(results);

    expect(report.total).toBe(3);
    expect(report.hits).toBe(2);
    expect(report.strictHitRate).toBeCloseTo(2 / 3);
    expect(report.avgEntityRecall).toBeCloseTo((1 + 0.5 + 1) / 3);
    expect(report.avgPhraseRecall).toBeCloseTo((1 + 0 + 1) / 3);
    expect(report.avgCombinedRecall).toBeCloseTo((1 + 0 + 1) / 3);
  });

  it('groups summaries by volume', () => {
    const report = aggregateResults([
      resultOf('v1-q1', 1, evaluationOf(true, 1, 1)),
      resultOf('v1-q2', 1, evaluationOf(false, 0, 0)),
      resultOf('v3-q1', 3, evaluationOf(true, 1, 1)),
    ]);

    expect(report.byVolume['1']).toEqual({
      total: 2,
      hits: 1,
      avgEntityRecall: 0.5,
      avgPhraseRecall: 0.5,
      avgCombinedRecall: 0.5,
    });
    expect(report.byVolume['3']).toEqual({
      total: 1,
      hits: 1,
      avgEntityRecall: 1,
      avgPhraseRecall: 1,
      avgCombinedRecall: 1,
    });
    expect(report.byVolume['2']).toBeUndefined();
  });
});

benchmark/run.ts.content:
import type { RetrievalResult } from '../retrieval/types/retrieval';
import type { RagApiClient } from './client';
import { createRagApiClient } from './client';
import { buildRetrievedContext } from './context';
import { BENCHMARK_QUERIES, type BenchmarkQuery } from './dataset';
import { evaluateRecall, type QueryEvaluation } from './evaluate';
import { formatMarkdownReport } from './format';
import type { BenchmarkReport, PerQueryResult } from './report';
import { aggregateResults } from './report';
import { buildAndWait } from './build';

/**
 * benchmark orchestration:
 * 1. (Optional) Build a RAG index via API using the outline folder and wait for completion
 * 2. For each benchmark query, call POST /api/rag/retrieve
 * 3. Evaluate recall and aggregate into a report
 *
 * `client` can be injected for testing; see `main` for the CLI entry.
 */

export interface RunBenchmarkOptions {
  client: RagApiClient;
  namespace: string;
  dataset?: readonly BenchmarkQuery[];
  outlinePath?: string;
  build?: boolean;
  topK?: number;
  includeAnswer?: boolean;
  /** Record each retrieval process (community/evidence count, context, evidence snippet preview), to troubleshoot recall anomalies. */
  verbose?: boolean;
  pollIntervalMs?: number;
  buildTimeoutMs?: number;
}

export interface BenchmarkOutcome {
  report: BenchmarkReport;
  results: PerQueryResult[];
}

export const runBenchmark = async (options: RunBenchmarkOptions): Promise<BenchmarkOutcome> => {
  const dataset = options.dataset ?? BENCHMARK_QUERIES;
  const includeAnswer = options.includeAnswer ?? false;

  if (options.build === true) {
    if (!options.outlinePath) {
      throw new Error('outlinePath is required when build is enabled');
    }
    await buildAndWait(options.client, {
      namespace: options.namespace,
      outlinePath: options.outlinePath,
      ...(options.pollIntervalMs !== undefined ? { pollIntervalMs: options.pollIntervalMs } : {}),
      ...(options.buildTimeoutMs !== undefined ? { buildTimeoutMs: options.buildTimeoutMs } : {}),
    });
  }

  const results: PerQueryResult[] = [];
  for (const query of dataset) {
    const topK = options.topK ?? query.topK;
    const retrieved = await retrieveOrThrow(options, query, topK);
    const context = buildRetrievedContext(retrieved, { includeAnswer });
    const evaluation = evaluateRecall(context, query.expectation);
    if (options.verbose === true) {
      logRetrievalFlow(query.id, retrieved, context, evaluation);
    }
    results.push({ query, evaluation });
  }

  return { report: aggregateResults(results), results };
};

const retrieveOrThrow = async (
  options: RunBenchmarkOptions,
  query: BenchmarkQuery,
  topK: number,
): Promise<RetrievalResult> => {
  try {
    return await options.client.retrieve({
      query: query.query,
      topK,
      namespace: options.namespace,
    });
  } catch (error) {
    if (options.verbose === true) {
      console.error(`[retrieve] ${query.id} FAILED: ${(error as Error).message}`);
    }
    throw error;
  }
};

const logRetrievalFlow = (
  id: string,
  retrieved: RetrievalResult,
  context: string,
  evaluation: QueryEvaluation,
): void => {
  console.log(
    `[retrieve] ${id} · communities=${retrieved.communities.length} evidence=${retrieved.evidence.length} ` +
      `context=${context.length} chars · entity recall=${evaluation.entityRecall} information recall=${evaluation.phraseRecall}`,
  );
  for (const [index, snippet] of retrieved.evidence.entries()) {
    console.log(`  evidence[${index}]: ${snippet.text.replace(/\s+/g, ' ').slice(0, 120)}`);
  }
};

export interface CliOptions {
  baseUrl: string;
  namespace: string;
  outlinePath: string;
  build: boolean;
  includeAnswer: boolean;
  verbose: boolean;
  topK: number | undefined;
}

const valueOf = (argv: readonly string[], flag: string): string | undefined => {
  const index = argv.indexOf(flag);
  return index >= 0 ? argv[index + 1] : undefined;
};

const parseTopK = (argv: readonly string[]): number | undefined => {
  const raw = valueOf(argv, '--topK');
  if (raw === undefined) {
    return undefined;
  }
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : undefined;
};

export const parseCliOptions = (
  argv: readonly string[],
  env: Record<string, string | undefined>,
): CliOptions => ({
  baseUrl: valueOf(argv, '--base-url') ?? env.RAG_API_BASE_URL ?? 'http://localhost:3000',
  namespace: valueOf(argv, '--namespace') ?? env.RAG_NAMESPACE ?? 'default-namespace',
  outlinePath:
    valueOf(argv, '--outline') ??
    env.RAG_OUTLINE_PATH ??
    '/Users/dushihua/dev/story-wirter/output/Retrospector/outline',
  build: argv.includes('--build'),
  includeAnswer: argv.includes('--include-answer'),
  verbose: argv.includes('--verbose'),
  topK: parseTopK(argv),
});

export const main = async (
  argv: readonly string[],
  env: Record<string, string | undefined>,
  clientFactory: (baseUrl: string) => RagApiClient = (baseUrl) =>
    createRagApiClient({ baseUrl }),
): Promise<void> => {
  const cli = parseCliOptions(argv, env);
  const outcome = await runBenchmark({
    client: clientFactory(cli.baseUrl),
    namespace: cli.namespace,
    outlinePath: cli.outlinePath,
    build: cli.build,
    includeAnswer: cli.includeAnswer,
    verbose: cli.verbose,
    ...(cli.topK !== undefined ? { topK: cli.topK } : {}),
  });
  console.log(formatMarkdownReport(outcome.report, outcome.results));
};

if (import.meta.main) {
  await main(process.argv.slice(2), process.env);
}

