import { describe, expect, it } from 'bun:test';

import { normalizeSlug } from './normalizeSlug';

describe('normalizeSlug', () => {
  it('passes through a valid slug unchanged', () => {
    expect(normalizeSlug('my-workspace')).toBe('my-workspace');
  });

  it('trims surrounding whitespace', () => {
    expect(normalizeSlug('  my-workspace  ')).toBe('my-workspace');
  });

  it('lowercases the input', () => {
    expect(normalizeSlug('My-Workspace')).toBe('my-workspace');
  });

  it('accepts a single character', () => {
    expect(normalizeSlug('a')).toBe('a');
  });

  it('accepts a leading digit', () => {
    expect(normalizeSlug('2fa')).toBe('2fa');
  });

  it('accepts the maximum length of 63 characters', () => {
    const slug = `${'a'.repeat(61)}-b`;
    expect(normalizeSlug(slug)).toBe(slug);
  });

  it('rejects an empty string', () => {
    expect(normalizeSlug('')).toBeUndefined();
  });

  it('rejects whitespace-only input', () => {
    expect(normalizeSlug('   ')).toBeUndefined();
  });

  it('rejects a leading hyphen', () => {
    expect(normalizeSlug('-abc')).toBeUndefined();
  });

  it('rejects an embedded space', () => {
    expect(normalizeSlug('my workspace')).toBeUndefined();
  });

  it('rejects an underscore', () => {
    expect(normalizeSlug('my_workspace')).toBeUndefined();
  });

  it('rejects a slug longer than 63 characters', () => {
    expect(normalizeSlug('a'.repeat(64))).toBeUndefined();
  });

  it('rejects non-ASCII characters', () => {
    expect(normalizeSlug('Workspace')).toBeUndefined();
  });
});

retrieval/types/graph.ts.content:
import type { Community, WeightedGraphEdge } from '../../build/detectCommunity';

export type EntityId = string;
export type CommunityId = string;

// Corresponds to RAGEntity (rag_entities) in the schema: id + name. Aliases/types are not in the schema, not modeled here.
export interface EntityRecord {
  id: EntityId;
  name: string;
}

// There is no alias table in the schema; it is provided by the caller (service layer) as an in-memory structure.
export interface EntityAlias {
  entityId: EntityId;
  alias: string;
}

export interface CommunityEdge extends WeightedGraphEdge {
  communityId: CommunityId;
  relationType?: string;
}

export interface CommunityRecord extends Community<string> {
  name?: string;
  summary?: string;
}

export interface CommunityMember {
  communityId: CommunityId;
  entityId: EntityId;
}

// "claim" now comes from the real table RAGClaim (rag_claims): entityIds are entity names (subject/object names),
// text is the original description; sourceDocumentId/sourceChunkId correspond to parent/child chunk provenance.
export interface ClaimRecord {
  id: string;
  entityIds: EntityId[];
  text: string;
  sourceDocumentId?: string;
  sourceChunkId?: string;
}

export interface EvidenceSnippet {
  claimId?: string;
  text: string;
  sourceDocumentId?: string;
  sourceChunkId?: string;
}

