import { prismaClient } from '../../build/helper/prismaClient';
import { logger } from '../../logger';
import { generateAnswer } from '../answer/answerGenerator';
import { embedText } from '../entity/embedding';
import { matchEntitiesWithSemantic } from '../entity/entityMatcher';
import { fetchCommunityDetails, getEntityNeighbors } from '../evidence/evidenceRetriever';
import { parseQuery } from '../query/queryParser';
import { rankCommunities } from '../ranking/communityRanker';
import { recallCommunitiesByTopology } from '../recall/communityResolver';
import {
  buildKeywordTerms,
  mergeChildChunks,
  searchChildChunksByKeywords,
} from '../recall/keywordSearch';
import {
  searchSimilarChildChunks,
  searchSimilarCommunitySummaries,
} from '../recall/vectorSearch';
import { selectFinalCommunities } from '../selection/finalSelector';
import type {
  ClaimRecord,
  CommunityEdge,
  CommunityId,
  CommunityMember,
  CommunityRecord,
  EntityRecord,
} from '../types/graph';
import type {
  CommunityDetails,
  EntityNeighborResult,
  MatchedEntity,
  RetrievalRequest,
  RetrievalResult,
} from '../types/retrieval';

interface LoadedEdge {
  id: string;
  parentId: string | null;
  source: string;
  target: string;
  relationType: string;
  weight: number;
  communityId: string | null;
}

/** Vector recall sub-block window. */
const VECTOR_CHILD_TOPK = 8;
/** Number of sub-blocks recalled by keyword (entity name + query term). */
const KEYWORD_SEARCH_LIMIT = 16;
/** Upper limit of evidence sub-blocks (after merging and deduplicating vector + keyword). */
const EVIDENCE_CHILD_LIMIT = 20;

const loadEntities = async (): Promise<EntityRecord[]> => {
  const rows = await prismaClient.rAGEntity.findMany({ select: { id: true, name: true } });
  return rows.map((row) => ({ id: row.id, name: row.name }));
};

const loadEdges = async (): Promise<LoadedEdge[]> => {
  const rows = await prismaClient.rAGGraphEdge.findMany({
    include: {
      sourceEntity: { select: { name: true } },
      targetEntity: { select: { name: true } },
    },
  });
  return rows.map((row) => ({
    id: row.id,
    parentId: row.parentId,
    source: row.sourceEntity.name,
    target: row.targetEntity.name,
    relationType: row.relationshipDesc,
    weight: row.weight,
    communityId: row.communitySummaryId,
  }));
};

const loadCommunities = async (
  ids: readonly CommunityId[],
  edges: readonly LoadedEdge[],
): Promise<CommunityRecord[]> => {
  const rows = await prismaClient.rAGCommunitySummary.findMany({
    where: { id: { in: [...ids] } },
  });

  const membersByCommunity = new Map<CommunityId, Set<string>>();
  for (const edge of edges) {
    if (!edge.communityId) {
      continue;
    }
    const members = membersByCommunity.get(edge.communityId) ?? new Set<string>();
    members.add(edge.source);
    members.add(edge.target);
    membersByCommunity.set(edge.communityId, members);
  }

  return rows.map((row) => ({
    id: row.id,
    name: row.communityName,
    summary: row.summaryContent,
    members: [...(membersByCommunity.get(row.id) ?? [])],
  }));
};

const toCommunityEdges = (edges: readonly LoadedEdge[]): CommunityEdge[] =>
  edges.map((edge) => ({
    source: edge.source,
    target: edge.target,
    communityId: edge.communityId ?? '',
    relationType: edge.relationType,
    weight: edge.weight,
  }));

const loadClaims = async (): Promise<ClaimRecord[]> => {
  const rows = await prismaClient.rAGClaim.findMany({
    include: {
      subjectEntity: { select: { name: true } },
      objectEntity: { select: { name: true } },
    },
  });

  if (rows.length === 0) {
    logger.warn('No claims found for this namespace; run a rebuild to populate rag_claims.');
  }

  return rows.map((row) => ({
    id: row.id,
    entityIds: [row.subjectEntity.name, ...(row.objectEntity ? [row.objectEntity.name] : [])],
    text: row.description,
    ...(row.sourceParentId ? { sourceDocumentId: row.sourceParentId } : {}),
    ...(row.sourceChunkId ? { sourceChunkId: row.sourceChunkId } : {}),
  }));
};

const toCommunityMembers = (edges: readonly LoadedEdge[]): CommunityMember[] => {
  const members: CommunityMember[] = [];
  for (const edge of edges) {
    if (!edge.communityId) {
      continue;
    }
    members.push({ communityId: edge.communityId, entityId: edge.source });
    members.push({ communityId: edge.communityId, entityId: edge.target });
  }
  return members;
};

const fuseMatchedWithIntent = (
  matched: readonly MatchedEntity[],
  intentEntities: readonly string[],
  entities: readonly EntityRecord[],
): MatchedEntity[] => {
  const byName = new Map<string, MatchedEntity>(matched.map((item) => [item.name, item]));

  for (const name of intentEntities) {
    const entity = entities.find((item) => item.name === name);
    if (entity && !byName.has(entity.name)) {
      byName.set(entity.name, {
        entityId: entity.id,
        name: entity.name,
        matchType: 'exact',
        score: 1,
      });
    }
  }

  return Array.from(byName.values());
};

export class GraphRAGRetrievalService {
  async retrieve(request: RetrievalRequest): Promise<RetrievalResult> {
    const { query } = request;
    const topK = request.topK ?? 5;

    const [entities, loadedEdges, claims] = await Promise.all([
      loadEntities(),
      loadEdges(),
      loadClaims(),
    ]);

    const intent = await parseQuery(query);
    const matchedByQuery = await matchEntitiesWithSemantic(query, entities, []);
    const matched = fuseMatchedWithIntent(matchedByQuery, intent.entities, entities);

    const { communityIds } = await recallCommunitiesByTopology(
      matched.map((item) => item.name),
      2,
    );

    const queryEmbedding = await embedText(query);
    const semanticRankings = (
      await searchSimilarCommunitySummaries(queryEmbedding, topK)
    ).map((hit) => hit.id);
    const childChunks = mergeChildChunks(
      await searchSimilarChildChunks(queryEmbedding, VECTOR_CHILD_TOPK),
      await searchChildChunksByKeywords(
        buildKeywordTerms({
          intentEntities: intent.entities,
          intentKeywords: intent.keywords,
          matched,
        }),
        KEYWORD_SEARCH_LIMIT,
      ),
      EVIDENCE_CHILD_LIMIT,
    );

    const candidateIds = Array.from(new Set([...communityIds, ...semanticRankings]));
    const communities = await loadCommunities(candidateIds, loadedEdges);
    const edges = toCommunityEdges(loadedEdges);

    const ranked = rankCommunities(
      candidateIds,
      communities,
      edges,
      matched.map((item) => item.name),
      semanticRankings,
      topK,
    );
    const selected = await selectFinalCommunities(query, ranked, true);

    const evidence = [
      ...selected.flatMap((community) =>
        fetchCommunityDetails(community.id, communities, edges, claims).evidence,
      ),
      ...childChunks.map((chunk) => ({
        text: chunk.content,
        sourceChunkId: chunk.id,
      })),
    ];

    const answer = await generateAnswer(
      query,
      selected.map((community) => community.summary ?? ''),
      evidence,
    );

    return { query, communities: selected, evidence, answer };
  }

  async getCommunityDetails(communityId: CommunityId): Promise<CommunityDetails> {
    const [loadedEdges, claims] = await Promise.all([loadEdges(), loadClaims()]);
    const communities = await loadCommunities([communityId], loadedEdges);
    const edges = toCommunityEdges(loadedEdges);

    return fetchCommunityDetails(communityId, communities, edges, claims);
  }

  async getEntityNeighbors(entityName: string, depth = 1): Promise<EntityNeighborResult> {
    const [entities, loadedEdges] = await Promise.all([loadEntities(), loadEdges()]);
    const edges = toCommunityEdges(loadedEdges);
    const communityMembers = toCommunityMembers(loadedEdges);

    return getEntityNeighbors(entityName, entities, edges, communityMembers, depth);
  }
}

import { describe, expect, it } from 'bun:test';

import { prismaClient } from '../../build/helper/prismaClient';
import { modelLoaderSingleton } from '../../build/modelLoader';
import { GraphRAGRetrievalService } from './GraphRAGRetrievalService';

describe('GraphRAGRetrievalService', () => {
  const originalModels = modelLoaderSingleton.models;
  const originalFindManyEntity = prismaClient.rAGEntity.findMany;
  const originalFindManyEdge = prismaClient.rAGGraphEdge.findMany;
  const originalFindManySummary = prismaClient.rAGCommunitySummary.findMany;
  const originalFindManyClaim = prismaClient.rAGClaim.findMany;
  const originalQueryRaw = prismaClient.$queryRaw;

  const entities = [
    { id: 'eA', name: 'A' },
    { id: 'eB', name: 'B' },
  ];
  const edgeRows = [
    {
      id: 'edge-1',
      parentId: 'p1',
      sourceEntityId: 'eA',
      targetEntityId: 'eB',
      sourceEntity: { name: 'A' },
      targetEntity: { name: 'B' },
      relationshipDesc: 'Cooperation',
      weight: 2,
      communitySummaryId: 'c1',
    },
  ];
  const summaries = [
    { id: 'c1', communityName: 'Community A', summaryContent: 'Summary of cooperation between A and B' },
  ];
  const claimRows = [
    {
      id: 'claim-1',
      subjectEntity: { name: 'A' },
      objectEntity: { name: 'B' },
      description: 'A and B have been partners for many years',
      sourceParentId: 'p1',
      sourceChunkId: 'child-1',
    },
  ];

  const installMocks = (sliceResponses: string[]) => {
    prismaClient.rAGEntity.findMany = (() => Promise.resolve(entities)) as never;
    prismaClient.rAGGraphEdge.findMany = (() => Promise.resolve(edgeRows)) as never;
    prismaClient.rAGCommunitySummary.findMany = ((args: unknown) => {
      const ids = (args as { where?: { id?: { in?: string[] } } })?.where?.id?.in;
      return Promise.resolve(ids ? summaries.filter((summary) => ids.includes(summary.id)) : summaries);
    }) as never;
    prismaClient.rAGClaim.findMany = (() => Promise.resolve(claimRows)) as never;
    prismaClient.$queryRaw = ((query: unknown) => {
      const text = JSON.stringify(query);
      if (text.includes('WITH RECURSIVE')) {
        return Promise.resolve([{ community_id: 'c1', entity_id: 'eA' }]);
      }
      if (text.includes('summary_embedding')) {
        return Promise.resolve([{ id: 'c1', similarity: 0.9 }]);
      }
      if (text.includes('rag_children') && text.includes('ILIKE')) {
        return Promise.resolve([
          { id: 'child-kw', content: 'Supplementary keyword sub-block for A and B', matches: 2 },
        ]);
      }
      if (text.includes('rag_children')) {
        return Promise.resolve([
          { id: 'child-9', content: 'Original sub-block of A and B's cooperation', similarity: 0.85 },
        ]);
      }
      return Promise.resolve([]);
    }) as never;
    modelLoaderSingleton.models = {
      slice: {
        invoke: async () => sliceResponses.shift() ?? '',
      },
      embedding: {
        embedQuery: async () => [0.1, 0.2],
      },
    } as never;
  };

  const restoreMocks = () => {
    prismaClient.rAGEntity.findMany = originalFindManyEntity;
    prismaClient.rAGGraphEdge.findMany = originalFindManyEdge;
    prismaClient.rAGCommunitySummary.findMany = originalFindManySummary;
    prismaClient.rAGClaim.findMany = originalFindManyClaim;
    prismaClient.$queryRaw = originalQueryRaw;
    modelLoaderSingleton.models = originalModels;
  };

  it('retrieves ranked communities with evidence and a generated answer', async () => {
    installMocks([
      JSON.stringify({ rawQuery: 'Background of cooperation between A and B', entities: ['A'], keywords: ['Cooperation'], themes: [] }),
      JSON.stringify({ selectedCommunityIds: ['c1'] }),
      'Answer: A and B have a cooperative relationship',
    ]);

    const service = new GraphRAGRetrievalService();
    try {
      const result = await service.retrieve({ query: 'Background of cooperation between A and B', topK: 5 });

      expect(result.answer).toBe('Answer: A and B have a cooperative relationship');
      expect(result.communities.map((community) => community.id)).toEqual(['c1']);
      expect(result.communities[0]?.matchedEntities).toContain('A');
      expect(result.communities[0]?.score).toBeTypeOf('number');
      expect(result.evidence).toEqual([
        {
          claimId: 'claim-1',
          text: 'A and B have been partners for many years',
          sourceDocumentId: 'p1',
          sourceChunkId: 'child-1',
        },
        { text: 'Original sub-block of A and B's cooperation', sourceChunkId: 'child-9' },
        { text: 'Supplementary keyword sub-block for A and B', sourceChunkId: 'child-kw' },
      ]);
    } finally {
      restoreMocks();
    }
  });

  it('returns community details with members, claims and evidence', async () => {
    installMocks([]);

    const service = new GraphRAGRetrievalService();
    try {
      const details = await service.getCommunityDetails('c1');

      expect(details.id).toBe('c1');
      expect(details.memberEntities).toEqual(['A', 'B']);
      expect(details.summary).toBe('Summary of cooperation between A and B');
      expect(details.relatedEdges.map((edge) => edge.source)).toEqual(['A']);
      expect(details.claims).toEqual([
        {
          id: 'claim-1',
          entityIds: ['A', 'B'],
          text: 'A and B have been partners for many years',
          sourceDocumentId: 'p1',
          sourceChunkId: 'child-1',
        },
      ]);
      expect(details.evidence).toEqual([
        {
          claimId: 'claim-1',
          text: 'A and B have been partners for many years',
          sourceDocumentId: 'p1',
          sourceChunkId: 'child-1',
        },
      ]);
    } finally {
      restoreMocks();
    }
  });

  it('throws when the requested community is missing', async () => {
    installMocks([]);

    const service = new GraphRAGRetrievalService();
    try {
      await expect(service.getCommunityDetails('missing')).rejects.toThrow();
    } finally {
      restoreMocks();
    }
  });

  it('returns entity neighbors with edge weight and community ids', async () => {
    installMocks([]);

    const service = new GraphRAGRetrievalService();
    try {
      const result = await service.getEntityNeighbors('A', 1);

      expect(result.neighbors).toEqual([
        { entityId: 'eB', entityName: 'B', relationType: 'Cooperation', weight: 2 },
      ]);
      expect(result.communityIds).toEqual(['c1']);
    } finally {
      restoreMocks();
    }
  });
});

retrieval/query/queryParser.test.ts.content:
import { describe, expect, it } from 'bun:test';

import { modelLoaderSingleton } from '../../build/modelLoader';
import { parseQuery } from './queryParser';

describe('parseQuery', () => {
  it('parses the query through the LLM into a QueryIntent', async () => {
    const originalModels = modelLoaderSingleton.models;

    modelLoaderSingleton.models = {
      embedding: {},
      slice: {
        invoke: async (prompt: string) => {
          expect(prompt).toContain('Apple and Banana Cooperation Background');
          return JSON.stringify({
            entities: ['Apple', 'Banana'],
            keywords: ['apple', 'banana'],
            themes: ['Cooperation'],
          });
        },
      },
    } as never;

    try {
      const intent = await parseQuery('Apple and Banana Cooperation Background');

      expect(intent.rawQuery).toBe('Apple and Banana Cooperation Background');
      expect(intent.entities).toEqual(['Apple', 'Banana']);
      expect(intent.keywords).toEqual(['apple', 'banana']);
      expect(intent.themes).toEqual(['Cooperation']);
    } finally {
      modelLoaderSingleton.models = originalModels;
    }
  });

  it('accepts markdown-fenced JSON from the slice model', async () => {
    const originalModels = modelLoaderSingleton.models;

    modelLoaderSingleton.models = {
      embedding: {},
      slice: {
        invoke: async () =>
          '```json\n' +
          JSON.stringify({
            entities: ['Apple'],
            keywords: ['apple'],
            themes: ['Cooperation'],
          }) +
          '\n```',
      },
    } as never;

    try {
      const intent = await parseQuery('Apple and Banana Cooperation Background');

      expect(intent.entities).toEqual(['Apple']);
    } finally {
      modelLoaderSingleton.models = originalModels;
    }
  });
});

