import type { OpenAIEmbeddings } from '@langchain/openai';
import { Prisma } from '@prisma/client';

import { getCurrentNamespace } from '../../../namespace/namespaceContext';
import { prismaClient } from '../../helper/prismaClient';
import { modelLoaderSingleton } from '../../modelLoader';
import { backfillCommunityAssignments } from './backfillCommunityAssignments';
import { buildCommunityContext, getCommunityContextMaxTokens } from './buildCommunityContext';
import { buildCommunityContextInput } from './buildCommunityContextInput';
import { generateCommunitySummary } from './generateCommunitySummary';
import type { CommunityDetectionResult } from '../types';

export const persistCommunitySummaries = async (
  result: CommunityDetectionResult,
  namespace: string,
) => {
  const embeddingModel = modelLoaderSingleton.models?.embedding as OpenAIEmbeddings | undefined;

  if (!embeddingModel) {
    throw new Error('Embedding model is not loaded. Please check the configuration for the embedding model.');
  }

  const [edgeRows, claimRows, entityRows, profileRows] = await Promise.all([
    prismaClient.rAGGraphEdge.findMany({
      orderBy: [{ sourceEntityId: 'asc' }, { targetEntityId: 'asc' }],
      include: {
        sourceEntity: { select: { name: true } },
        targetEntity: { select: { name: true } },
      },
    }),
    prismaClient.rAGClaim.findMany({
      include: {
        subjectEntity: { select: { name: true } },
        objectEntity: { select: { name: true } },
      },
    }),
    prismaClient.rAGEntity.findMany({ select: { id: true, name: true, description: true } }),
    prismaClient.entityProfile.findMany({ select: { entityId: true, profile: true } }),
  ]);

  const profileByEntityId = new Map(
    profileRows.map((profile) => [profile.entityId, profile.profile]),
  );

  // M6 (one-way read-only): [Node Summary] prefers reading EntityProfile (canonical profile), on miss falls back to description extracted by build.
  const entityDescriptions = new Map(
    entityRows.map((entity) => [
      entity.name,
      profileByEntityId.get(entity.id) ?? entity.description,
    ]),
  );

  const memberToCommunity = new Map<string, number>();
  result.communities.forEach((community) => {
    community.members.forEach((member) => {
      memberToCommunity.set(member, community.id);
    });
  });

  const communitySummaries = new Map<number, { id: string; name: string }>();
  for (const community of result.communities) {
    const input = buildCommunityContextInput(community, edgeRows, claimRows, entityDescriptions);
    const inputContent = buildCommunityContext(input, {
      maxTokens: getCommunityContextMaxTokens(),
    });
    const { communityName, summaryContent } = await generateCommunitySummary(community, inputContent);
    const summary = await prismaClient.rAGCommunitySummary.create({
      data: {
        namespace,
        communityName,
        summaryContent,
      },
    });

    const summaryEmbedding = await embeddingModel.embedQuery(summaryContent);
    await prismaClient.$executeRaw(Prisma.sql`
      UPDATE "rag_community_summaries"
      SET "summary_embedding" = CAST(${JSON.stringify(summaryEmbedding)} AS vector)
      WHERE "id" = ${summary.id}
        AND "namespace" = ${getCurrentNamespace()}
    `);

    communitySummaries.set(community.id, { id: summary.id, name: communityName });
  }

  await backfillCommunityAssignments(edgeRows, claimRows, memberToCommunity, communitySummaries);
};

build/markdownStructureSplit.ts.content:
import { lexer, parser, type Token, type Tokens } from 'marked';

export interface MarkdownSection {
  title: string;
  content: string;
  headingLevel: number;
}

const headingTokens = (markdown: string): Tokens.Heading[] =>
  lexer(markdown).filter((token) => token.type === 'heading') as Tokens.Heading[];

/** Extract top-level heading level: if h1 count is sufficient (>=2), use h1; otherwise fall back to h2; if both are scarce, revert to h1. */
export const resolveTopLevelHeading = (markdown: string): number => {
  const headings = headingTokens(markdown);
  const h1 = headings.filter((h) => h.depth === 1).length;
  const h2 = headings.filter((h) => h.depth === 2).length;
  if (h1 >= 2) return 1;
  if (h2 >= 2) return 2;
  return 1;
};

const renderToken = (token: Token): string => parser([token]);

/** Split by top-level headings; content before the top-level heading goes into the first untitled preamble block. */
export const splitByTopLevelHeadings = (markdown: string): MarkdownSection[] => {
  const topLevel = resolveTopLevelHeading(markdown);
  const sections: MarkdownSection[] = [];
  let current: MarkdownSection | null = null;
  let preamble: string[] = [];

  for (const token of lexer(markdown)) {
    if (token.type === 'heading' && token.depth === topLevel) {
      if (current) {
        sections.push(current);
      } else if (preamble.length > 0) {
        sections.push({ title: '', content: preamble.join('\n\n'), headingLevel: topLevel });
        preamble = [];
      }
      current = { title: token.text, content: '', headingLevel: topLevel };
    } else if (current) {
      current.content = current.content ? `${current.content}\n\n${renderToken(token)}` : renderToken(token);
    } else {
      preamble.push(renderToken(token));
    }
  }
  if (current) sections.push(current);
  if (preamble.length > 0) {
    sections.push({ title: '', content: preamble.join('\n\n'), headingLevel: topLevel });
  }
  return sections;
};

/** Merge overly small adjacent blocks: large blocks (>=minSize) are kept independently, small blocks accumulate into reasonable input intervals, reducing the number of LLM calls. */
export const mergeSmallSections = (
  sections: readonly MarkdownSection[],
  minSize: number,
): MarkdownSection[] => {
  const merged: MarkdownSection[] = [];
  let buffer: MarkdownSection | null = null;

  for (const section of sections) {
    if (section.content.length >= minSize) {
      if (buffer) {
        merged.push(buffer);
        buffer = null;
      }
      merged.push({ ...section });
      continue;
    }

    if (!buffer) {
      buffer = { ...section };
    } else {
      buffer = {
        title: buffer.title ? `${buffer.title} / ${section.title}` : section.title,
        content: `${buffer.content}\n\n${section.content}`,
        headingLevel: buffer.headingLevel,
      };
    }
  }
  if (buffer) merged.push(buffer);
  return merged;
};

build/textSplit.ts.content:
import { CustomModelConfigType } from "./custom.model.conf.type";
import { invokeModelText, modelLoaderSingleton } from "./modelLoader";
import { logger } from "../logger";
import type { ChatDeepSeek } from "@langchain/deepseek";
import type { OpenAIEmbeddings } from "@langchain/openai";
import { RecursiveCharacterTextSplitter } from "@langchain/textsplitters";
import {
  DETERMINISTIC_THRESHOLD,
  MARKDOWN_STRUCTURE_THRESHOLD,
  MAX_CHUNK_SIZE,
  MERGE_THRESHOLD,
} from "./constants";
import { prismaClient } from "./helper/prismaClient";
import { buildChildInsertSql } from "./helper/buildChildInsertSql";
import { agentRegistry } from "./agents.md/agentRegistry";
import { assmblyAgent } from "./agents.md/assmblyAgent";
import { parseLlmJson } from "../helper/parseLlmJson";
import { mergeSmallSections, splitByTopLevelHeadings } from "./markdownStructureSplit";
export interface ChunkEdge {
  source: string;
  target: string;
  relation: string;
}

export interface ChunkClaim {
  subject: string;
  object?: string;
  description: string;
  childIndex?: number;
}

export interface ChunkEntity {
  name: string;
  description?: string;
}

interface ChunkResult {
  parentContent: string;
  childChunks: string[];
  edges: ChunkEdge[];
  claims: ChunkClaim[];
  entities: ChunkEntity[];
}

export interface SplitResult {
  parentId: string;
  childIds: string[];
  edges: ChunkEdge[];
  claims: ChunkClaim[];
  entities: ChunkEntity[];
}

export interface TextSplitInput {
  content: string;
  title?: string;
  namespace: string;
}


export type TextSplitMode = 'auto' | 'llm' | 'deterministic';

export interface TextSplitInput {
  content: string;
  title?: string;
  namespace: string;
  mode?: TextSplitMode;
}

/** .md extension priority, fallback to markdown heading lines in content. */
const isMarkdown = (content: string, title?: string): boolean => {
  const byName = title ? /\.md$/i.test(title) : false;
  const byContent = /^#{1,6}\s+\S+/m.test(content);
  return byName || byContent;
};


const getSmartChunk = async (content: string, sliceModel: ChatDeepSeek, contextTitle?: string): Promise<ChunkResult[]> => {
  // In structure splitting scenario, inject current section title to help LLM focus on entity/relation extraction.
  const prompt = await assmblyAgent(
    contextTitle ? `[current section: ${contextTitle}]\n${content}` : content,
    agentRegistry.ragSliceAgent,
  );
  const response = await invokeModelText(sliceModel, prompt);
  const backupSplitter = new RecursiveCharacterTextSplitter({
    chunkSize: MAX_CHUNK_SIZE,
    chunkOverlap: MAX_CHUNK_SIZE / 10, // 10% overlap
  });

  try {
    // In JSON mode, the output may be an array [{...}], or it may be a wrapped object { \"chunks\": [...] }, both are compatible.
    const parsed = parseLlmJson<Partial<ChunkResult>[] | { chunks?: Partial<ChunkResult>[] }>(response);
    const rawChunks = Array.isArray(parsed) ? parsed : (parsed?.chunks ?? []);
    const llmChunks = rawChunks.map((chunk) => ({
      ...chunk,
      parentContent: chunk.parentContent ?? '',
      childChunks: chunk.childChunks ?? [],
      edges: chunk.edges ?? [],
      claims: chunk.claims ?? [],
      entities: chunk.entities ?? [],
    }));

    // Quality gate: if chunks is empty or has no entities/edges (completely empty), it is considered untrustworthy, fallback to deterministic splitting.
    const hasSignal = llmChunks.some((chunk) => chunk.entities.length > 0 || chunk.edges.length > 0);
    if (llmChunks.length === 0 || !hasSignal) {
      throw new Error('LLM chunking output is empty (no entities/edges)');
    }

    return await Promise.all(llmChunks.map(async (chunk) => {
      if (chunk.parentContent.length > MAX_CHUNK_SIZE) {
        const backupChunks = await backupSplitter.splitText(chunk.parentContent);
        return {
          ...chunk,
          childChunks: backupChunks,
        };
      }
      return chunk;
    }));

  } catch (error) {
    logger.warn('LLM chunking output unavailable, fallback to deterministic splitting', error);
    const fallbackChunks = await backupSplitter.splitText(content);
    return [{
      parentContent: content,
      childChunks: fallbackChunks,
      edges: [],
      claims: [],
      entities: [],
    }];
  }
};


const saveChunkResults = async (
  results: ChunkResult[],
  embeddingModel: OpenAIEmbeddings,
  namespace: string,
  title?: string,
): Promise<SplitResult[]> => {
  return Promise.all(
    results.map((chunk) =>
      prismaClient.$transaction(async (tx) => {
        const parent = await tx.rAGParent.create({
          data: {
            namespace,
            content: chunk.parentContent,
            ...(title ? { title } : {}),
          },
        });

        const createdChildren = await Promise.all(
          chunk.childChunks.map(async (childContent) => ({
            parentId: parent.id,
            content: childContent,
            embedding: await embeddingModel.embedQuery(childContent),
          }))
        );

        let childIds: string[] = [];
        if (createdChildren.length > 0) {
          const inserted = await tx.$queryRaw<{ id: string }[]>(
            buildChildInsertSql(createdChildren, namespace),
          );
          childIds = inserted.map((row) => row.id);
        }

        return {
          parentId: parent.id,
          childIds,
          edges: chunk.edges,
          claims: chunk.claims,
          entities: chunk.entities,
        };
      })
    )
  );
};

/** Deterministic splitting: RecursiveCharacterTextSplitter, no entities/edges/assertions. */
const deterministicSplit = async (
  content: string,
  embeddingModel: OpenAIEmbeddings,
  namespace: string,
  title?: string,
): Promise<SplitResult[]> => {
  const splitter = new RecursiveCharacterTextSplitter({
    chunkSize: MAX_CHUNK_SIZE,
    chunkOverlap: MAX_CHUNK_SIZE / 10,
  });
  const chunks = await splitter.splitText(content);
  return saveChunkResults(
    [{ parentContent: content, childChunks: chunks, edges: [], claims: [], entities: [] }],
    embeddingModel,
    namespace,
    title,
  );
};

/** LLM semantic splitting: JSON mode structured output, failure/empty internally falls back to deterministic by getSmartChunk. */
const llmSplit = async (
  content: string,
  sliceModel: ChatDeepSeek,
  embeddingModel: OpenAIEmbeddings,
  namespace: string,
  title?: string,
): Promise<SplitResult[]> => {
  const smartChunk = await getSmartChunk(content, sliceModel, title);
  return saveChunkResults(smartChunk, embeddingModel, namespace, title);
};

/** markdown too long: split by top-level headings → merge small segments → each segment serially LLM semantic splitting (paragraph-level fallback). */
const markdownStructureSplit = async (
  content: string,
  sliceModel: ChatDeepSeek,
  embeddingModel: OpenAIEmbeddings,
  namespace: string,
  title?: string,
): Promise<SplitResult[]> => {
  const sections = mergeSmallSections(splitByTopLevelHeadings(content), MERGE_THRESHOLD);
  const results: SplitResult[] = [];

  for (const section of sections) {
    // Title injected into parent block title for traceability; within-segment LLM failure falls back independently via getSmartChunk, not affecting other segments.
    const sectionTitle = title ? `${title}#${section.title}` : (section.title || undefined);
    const smartChunk = await getSmartChunk(section.content, sliceModel, section.title);
    results.push(...(await saveChunkResults(smartChunk, embeddingModel, namespace, sectionTitle)));
  }
  return results;
};

export const textSplit = async (input: TextSplitInput): Promise<SplitResult[]> => {
  const { content, title, namespace, mode = 'auto' } = input;

  try {
    if (!modelLoaderSingleton.models?.embedding) {
      throw new Error(`Embedding model is not loaded. Please check the configuration for ${CustomModelConfigType.embedding}.`);
    }
    if (!modelLoaderSingleton.models?.slice) {
      throw new Error(`Slice model is not loaded. Please check the configuration for ${CustomModelConfigType.slice}.`);
    }
    const embeddingModel = modelLoaderSingleton.models.embedding;
    const sliceModel = modelLoaderSingleton.models.slice;

    // Explicit mode takes precedence: deterministic forces deterministic, llm forces LLM (not affected by short text threshold).
    if (mode === 'deterministic') {
      return deterministicSplit(content, embeddingModel as OpenAIEmbeddings, namespace, title);
    }

    if (mode === 'llm') {
      return llmSplit(content, sliceModel, embeddingModel as OpenAIEmbeddings, namespace, title);
    }

    // auto: short text is not worth paying LLM cost, directly deterministic splitting.
    if (content.length < DETERMINISTIC_THRESHOLD) {
      return deterministicSplit(content, embeddingModel as OpenAIEmbeddings, namespace, title);
    }

    // auto: overlong markdown first splits into blocks by heading structure, then LLM per segment, others directly LLM semantic splitting.
    if (content.length > MARKDOWN_STRUCTURE_THRESHOLD && isMarkdown(content, title)) {
      return markdownStructureSplit(content, sliceModel, embeddingModel as OpenAIEmbeddings, namespace, title);
    }
    return llmSplit(content, sliceModel, embeddingModel as OpenAIEmbeddings, namespace, title);
  } catch (error) {
    logger.error(error);
    throw error;
  }
};

