import { describe, expect, it } from 'bun:test';

import { buildClaims, descriptionHash } from './buildClaims';
import { prismaClient } from './prismaClient';

describe('descriptionHash', () => {
  it('is a 64-char sha256 hex over trimmed lowercase text', () => {
    const hash = descriptionHash('  Hello World  ');
    expect(hash).toMatch(/^[0-9a-f]{64}$/);
    expect(hash).toBe(descriptionHash('hello world'));
    //No folding spaces: different phrasings are not merged
    expect(hash).not.toBe(descriptionHash('hello  world'));
  });
});

describe('buildClaims', () => {
  const originalEntityUpsert = prismaClient.rAGEntity.upsert;
  const originalCreateMany = prismaClient.rAGClaim.createMany;

  const stubEntityUpsert = () => {
    const calls: Array<{ where: { namespace_name: { namespace: string; name: string } } }> = [];
    prismaClient.rAGEntity.upsert = ((args: unknown) => {
      calls.push(args as never);
      const { where } = args as { where: { namespace_name: { namespace: string; name: string } } };
      return Promise.resolve({ id: `entity-${where.namespace_name.name}` }) as never;
    }) as typeof prismaClient.rAGEntity.upsert;
    return calls;
  };

  const stubCreateMany = () => {
    const calls: Array<{ data: unknown[]; skipDuplicates?: boolean }> = [];
    prismaClient.rAGClaim.createMany = ((args: unknown) => {
      const { data, skipDuplicates } = args as { data: unknown[]; skipDuplicates?: boolean };
      calls.push(skipDuplicates === undefined ? { data } : { data, skipDuplicates });
      return Promise.resolve({ count: data.length }) as never;
    }) as typeof prismaClient.rAGClaim.createMany;
    return calls;
  };

  const restore = () => {
    prismaClient.rAGEntity.upsert = originalEntityUpsert;
    prismaClient.rAGClaim.createMany = originalCreateMany;
  };

  it('returns 0 without touching the db when there are no claims', async () => {
    const entityCalls = stubEntityUpsert();
    const createCalls = stubCreateMany();
    try {
      const count = await buildClaims([], { parentId: 'p', childIds: ['c'], namespace: 'ns-a' });
      expect(count).toBe(0);
      expect(entityCalls).toHaveLength(0);
      expect(createCalls).toHaveLength(0);
    } finally {
      restore();
    }
  });

  it('upserts subject and object entities and maps childIndex to sourceChunkId', async () => {
    const entityCalls = stubEntityUpsert();
    const createCalls = stubCreateMany();
    try {
      const count = await buildClaims(
        [
          { subject: 'Alpha', object: 'Beta', description: 'Alpha leads Beta', childIndex: 1 },
          { subject: 'Gamma', description: 'Gamma is standalone' },
        ],
        { parentId: 'parent-1', childIds: ['child-0', 'child-1', 'child-2'], namespace: 'ns-a' },
      );

      expect(count).toBe(2);
      const names = entityCalls.map((c) => c.where.namespace_name.name);
      expect(names.sort()).toEqual(['Alpha', 'Beta', 'Gamma']);
      expect(entityCalls.every((c) => c.where.namespace_name.namespace === 'ns-a')).toBe(true);

      const data = createCalls[0]?.data as Array<Record<string, unknown>>;
      expect(data[0]).toMatchObject({
        namespace: 'ns-a',
        subjectEntityId: 'entity-Alpha',
        objectEntityId: 'entity-Beta',
        description: 'Alpha leads Beta',
        sourceParentId: 'parent-1',
        sourceChunkId: 'child-1',
      });
      expect(data[1]).toMatchObject({
        subjectEntityId: 'entity-Gamma',
      });
      expect(data[1]).not.toHaveProperty('objectEntityId');
      expect(data[1]).not.toHaveProperty('sourceChunkId');
    } finally {
      restore();
    }
  });

  it('drops out-of-range childIndex to parent-level traceability', async () => {
    stubEntityUpsert();
    const createCalls = stubCreateMany();
    try {
      await buildClaims(
        [{ subject: 'Alpha', description: 'fact', childIndex: 99 }],
        { parentId: 'parent-1', childIds: ['child-0'], namespace: 'ns-a' },
      );
      const data = createCalls[0]?.data as Array<Record<string, unknown>>;
      expect(data[0]).not.toHaveProperty('sourceChunkId');
    } finally {
      restore();
    }
  });

  it('emits identical description hashes for duplicate facts so the db can dedupe', async () => {
    stubEntityUpsert();
    const createCalls = stubCreateMany();
    try {
      await buildClaims(
        [
          { subject: 'Alpha', description: 'Alpha is the protagonist' },
          { subject: 'Alpha', description: 'Alpha is the protagonist' },
          { subject: 'Alpha', description: 'alpha is the protagonist' },
        ],
        { parentId: 'parent-1', childIds: [], namespace: 'ns-a' },
      );
      const data = createCalls[0]?.data as Array<Record<string, unknown>>;
      expect(data).toHaveLength(3);
      const hashes = new Set(data.map((row) => row.descriptionHash));
      expect(hashes.size).toBe(1);
      expect(createCalls[0]?.skipDuplicates).toBe(true);
    } finally {
      restore();
    }
  });
});

build/helper/buildEdges.ts.content:
import { prismaClient } from './prismaClient';

export interface GraphEdge {
  source: string;
  target: string;
}

export interface ChunkEdge extends GraphEdge {
  relation: string;
  weight: number;
}

const normalizeRelation = (relation: string) =>
  relation.trim().toLowerCase().replace(/\s+/g, '_');

const normalizeWeight = (weight: number) => {
  if (!Number.isFinite(weight)) {
    return 1;
  }

  return Math.min(5, Math.max(1, Math.round(weight)));
};

export const normalizeEdgeEntities = (sourceEntity: string, targetEntity: string) => {
  const left = sourceEntity.trim();
  const right = targetEntity.trim();

  return left.localeCompare(right) <= 0
    ? { sourceEntity: left, targetEntity: right }
    : { sourceEntity: right, targetEntity: left };
};

interface AggregatedEdge {
  sourceEntity: string;
  targetEntity: string;
  relationshipDesc: string;
  weight: number;
  parentId: string | null;
}

/** Aggregate edges by normalized (source::target) and accumulate weights. */
const aggregateEdges = (chunks: ChunkEdge[], parentId: string | null): AggregatedEdge[] => {
  const byPair = new Map<string, AggregatedEdge>();
  for (const { source, target, relation, weight } of chunks) {
    const { sourceEntity, targetEntity } = normalizeEdgeEntities(source, target);
    const key = `${sourceEntity}::${targetEntity}`;
    const current = byPair.get(key) ?? {
      sourceEntity,
      targetEntity,
      relationshipDesc: normalizeRelation(relation),
      weight: 0,
      parentId,
    };
    current.relationshipDesc = normalizeRelation(relation);
    current.parentId = parentId;
    current.weight += normalizeWeight(weight);
    byPair.set(key, current);
  }
  return [...byPair.values()];
};

/** Serially upsert all unique entities and resolve ids, avoiding unique constraint conflicts from parallel upserts when multiple edges share an entity. */
const resolveEntities = async (
  edges: readonly AggregatedEdge[],
  namespace: string,
): Promise<Map<string, { id: string }>> => {
  const names = new Set<string>();
  for (const { sourceEntity, targetEntity } of edges) {
    names.add(sourceEntity);
    names.add(targetEntity);
  }

  const records = new Map<string, { id: string }>();
  for (const name of names) {
    const record = await prismaClient.rAGEntity.upsert({
      where: { namespace_name: { namespace, name } },
      update: {},
      create: { namespace, name },
    });
    records.set(name, record);
  }
  return records;
};

const upsertEdge = (
  edge: AggregatedEdge,
  entityRecords: ReadonlyMap<string, { id: string }>,
  parentId: string | null,
  namespace: string,
) => {
  const sourceRecord = entityRecords.get(edge.sourceEntity);
  const targetRecord = entityRecords.get(edge.targetEntity);
  if (!sourceRecord || !targetRecord) {
    throw new Error(`Entity record not found for edge ${edge.sourceEntity}->${edge.targetEntity}`);
  }

  return prismaClient.rAGGraphEdge.upsert({
    where: {
      namespace_sourceEntityId_targetEntityId: {
        namespace,
        sourceEntityId: sourceRecord.id,
        targetEntityId: targetRecord.id,
      },
    },
    update: {
      parentId,
      relationshipDesc: edge.relationshipDesc,
      weight: {
        increment: edge.weight,
      },
    },
    create: {
      namespace,
      sourceEntityId: sourceRecord.id,
      targetEntityId: targetRecord.id,
      relationshipDesc: edge.relationshipDesc,
      parentId,
      weight: edge.weight,
    },
  });
};

export const buildEdges = async (
  chunks: ChunkEdge[],
  parentId: string | null,
  namespace: string,
) => {
  if (chunks.length === 0) {
    return [];
  }

  const edges = aggregateEdges(chunks, parentId);
  const entityRecords = await resolveEntities(edges, namespace);
  return Promise.all(edges.map((edge) => upsertEdge(edge, entityRecords, parentId, namespace)));
};

