import { prismaClient } from './prismaClient';

export interface ChunkEntity {
  name: string;
  description?: string;
}

/** Entity description overwrite: when description is empty, the existing value is not updated. */
export const buildEntities = async (
  entities: readonly ChunkEntity[],
  namespace: string,
): Promise<number> => {
  if (entities.length === 0) {
    return 0;
  }

  let written = 0;
  for (const entity of entities) {
    const name = entity.name.trim();
    const description = entity.description?.trim();
    if (!name) {
      continue;
    }
    await prismaClient.rAGEntity.upsert({
      where: { namespace_name: { namespace, name } },
      update: description ? { description } : {},
      create: { namespace, name, ...(description ? { description } : {}) },
    });
    written += 1;
  }

  return written;
};

build/helper/buildChildInsertSql.ts.content:
import { Prisma } from '@prisma/client';

interface ChildInsertRow {
  parentId: string;
  content: string;
  embedding: number[];
}

export const buildChildInsertSql = (children: ChildInsertRow[], namespace: string) => {
  if (children.length === 0) {
    return Prisma.sql``;
  }

  // id/updated_at has no DEFAULT at the database layer (Prisma's @default(cuid())/@updatedAt are only generated at the Client layer),
  // Native SQL inserts must be explicitly provided, otherwise they violate the NOT NULL constraint (23502).
  return Prisma.sql`
    INSERT INTO "rag_children" ("id", "namespace", "content", "parent_id", "embedding", "fts_tokens", "updated_at")
    VALUES ${Prisma.join(
      children.map(({ parentId, content, embedding }) =>
        Prisma.sql`(${crypto.randomUUID()}, ${namespace}, ${content}, ${parentId}, CAST(${JSON.stringify(embedding)} AS vector), to_tsvector('english', ${content}), now())`
      ),
      ','
    )}
    RETURNING "id"
  `;
};

build/helper/buildClaims.ts.content:
import { createHash } from 'node:crypto';

import { prismaClient } from './prismaClient';

export interface ChunkClaim {
  subject: string;
  object?: string;
  description: string;
  childIndex?: number;
}

interface ClaimRow {
  namespace: string;
  subjectEntityId: string;
  objectEntityId?: string;
  description: string;
  descriptionHash: string;
  sourceParentId: string;
  sourceChunkId?: string;
}

interface BuildClaimsOptions {
  parentId: string;
  childIds: readonly string[];
  namespace: string;
}

/** Only for generating dedup hash: trim + lowercase, no space folding, to avoid excessive merging. */
const normalizeForHash = (text: string) => text.trim().toLowerCase();

export const descriptionHash = (text: string) =>
  createHash('sha256').update(normalizeForHash(text), 'utf8').digest('hex');

const collectEntityNames = (claims: readonly ChunkClaim[]): string[] => {
  const names = new Set<string>();
  for (const claim of claims) {
    const subject = claim.subject.trim();
    if (subject) {
      names.add(subject);
    }
    const object = claim.object?.trim();
    if (object) {
      names.add(object);
    }
  }
  return [...names];
};

const resolveEntityIds = async (names: readonly string[], namespace: string) => {
  const entityIds = new Map<string, string>();
  await Promise.all(
    names.map(async (name) => {
      const record = await prismaClient.rAGEntity.upsert({
        where: { namespace_name: { namespace, name } },
        update: {},
        create: { namespace, name },
      });
      entityIds.set(name, record.id);
    }),
  );
  return entityIds;
};

const resolveSourceChunkId = (
  childIds: readonly string[],
  childIndex: number | undefined,
): string | null => {
  if (childIndex == null || childIndex < 0 || childIndex >= childIds.length) {
    return null;
  }
  return childIds[childIndex] ?? null;
};

const toClaimRows = (
  claims: readonly ChunkClaim[],
  opts: BuildClaimsOptions,
  entityIds: ReadonlyMap<string, string>,
): ClaimRow[] => {
  const rows: ClaimRow[] = [];
  for (const claim of claims) {
    const subject = claim.subject.trim();
    const subjectEntityId = entityIds.get(subject);
    if (!subject || !subjectEntityId) {
      continue;
    }

    const objectName = claim.object?.trim();
    const objectEntityId = objectName ? entityIds.get(objectName) : undefined;
    const sourceChunkId = resolveSourceChunkId(opts.childIds, claim.childIndex);

    rows.push({
      namespace: opts.namespace,
      subjectEntityId,
      ...(objectEntityId ? { objectEntityId } : {}),
      description: claim.description,
      descriptionHash: descriptionHash(claim.description),
      sourceParentId: opts.parentId,
      ...(sourceChunkId ? { sourceChunkId } : {}),
    });
  }
  return rows;
};

export const buildClaims = async (
  claims: readonly ChunkClaim[],
  opts: BuildClaimsOptions,
): Promise<number> => {
  if (claims.length === 0) {
    return 0;
  }

  const entityIds = await resolveEntityIds(collectEntityNames(claims), opts.namespace);
  const rows = toClaimRows(claims, opts, entityIds);

  if (rows.length === 0) {
    return 0;
  }

  const result = await prismaClient.rAGClaim.createMany({
    data: rows,
    skipDuplicates: true,
  });

  return result.count;
};

helper/parseLlmJson.ts.content:
/**
 * Parse JSON from LLM output.
 * LLMs often wrap JSON in Markdown code blocks or add explanatory text before/after, so directly calling JSON.parse
 * will throw "JSON format detection error". Here we use fault-tolerant extraction:
 *  1. Remove the ```json ... ``` code block wrapper;
 *  2. Directly call JSON.parse;
 *  3. On failure, extract the substring from the first [ or { to the matching trailing ] or } and parse it.
 * If it still fails, throw an error containing a preview of the original output to help locate the real cause in logs.
 */

const FENCE_PATTERN = /```(?:json)?\s*([\s\S]*?)```/i;

const stripFences = (raw: string): string => {
  const fenced = raw.match(FENCE_PATTERN);
  return fenced?.[1] ?? raw;
};

const extractJsonSlice = (text: string): string | null => {
  const start = text.search(/[[{]/);
  if (start === -1) return null;
  const open = text[start]!;
  const close = open === '[' ? ']' : '}';
  const end = text.lastIndexOf(close);
  if (end <= start) return null;
  return text.slice(start, end + 1);
};

const preview = (raw: string): string => (raw.length > 200 ? `${raw.slice(0, 200)}…` : raw);

export const parseLlmJson = <T>(raw: string): T => {
  const stripped = stripFences(raw);
  try {
    return JSON.parse(stripped) as T;
  } catch {
    const slice = extractJsonSlice(stripped);
    if (slice !== null) {
      try {
        return JSON.parse(slice) as T;
      } catch {
        // fall through to the error below
      }
    }
    throw new Error(`LLM output is not valid JSON: ${preview(raw)}`);
  }
};

helper/parseLlmJson.test.ts.content:
import { describe, expect, it } from 'bun:test';

import { parseLlmJson } from './parseLlmJson';

describe('parseLlmJson', () => {
  it('parses plain JSON', () => {
    expect(parseLlmJson<{ answer: string }>('{"answer":"ok"}')).toEqual({ answer: 'ok' });
  });

  it('strips a markdown json code fence', () => {
    const raw = '```json\n{"answer":"ok"}\n```';
    expect(parseLlmJson<{ answer: string }>(raw)).toEqual({ answer: 'ok' });
  });

  it('strips a code fence without a language tag', () => {
    const raw = '```\n{"answer":"ok"}\n```';
    expect(parseLlmJson<{ answer: string }>(raw)).toEqual({ answer: 'ok' });
  });

  it('parses a JSON array wrapped in a fence', () => {
    const raw = '```json\n[{"parentContent":"p"}]\n```';
    expect(parseLlmJson<{ parentContent: string }[]>(raw)).toEqual([{ parentContent: 'p' }]);
  });

  it('extracts JSON embedded in surrounding prose', () => {
    const raw = 'The results are as follows: \n{"answer":"ok"}\n Please check.';
    expect(parseLlmJson<{ answer: string }>(raw)).toEqual({ answer: 'ok' });
  });

  it('throws with a preview of the raw output when no JSON is present', () => {
    expect(() => parseLlmJson('Sorry, I cannot understand your request.')).toThrow(/not valid JSON/);
  });

  it('truncates long raw output in the error preview', () => {
    const raw = 'x'.repeat(300);
    expect(() => parseLlmJson(raw)).toThrow(/x{200}…/);
  });
});
